/**
 * Design process — how requirements turn into interfaces developers can build.
 */
export const process = {
	title: "Design Process",
	subtitle:
		"As a UI/UX designer, I make sure that my designs are well received by users, and can be implemented by developers.",
	items: [
		{
			id: "01",
			icon: "bi bi-search",
			title: "Research",
			description:
				"Requirements and market research up front, so the solution matches what users and the business actually need.",
		},
		{
			id: "02",
			icon: "bi bi-diagram-3",
			title: "Flow Documentation",
			description:
				"User flows documented so the product can be extended and maintained without losing the original intent.",
		},
		{
			id: "03",
			icon: "bi bi-clipboard-check",
			title: "UI Audit",
			description:
				"A full audit of the interface to catch inconsistencies and issues before the build begins.",
		},
		{
			id: "04",
			icon: "bi bi-people",
			title: "User Testing",
			description:
				"Usability and A/B testing to validate that a design performs well with real users before it ships.",
		},
		{
			id: "05",
			icon: "bi bi-boxes",
			title: "Provide Assets",
			description:
				"UI assets exported and organised in the sizes and formats development actually needs.",
		},
		{
			id: "06",
			icon: "bi bi-file-earmark-text",
			title: "UI Documentation",
			description:
				"Detailed UI documentation and redlines so developers can build from the design without guesswork.",
		},
	],
};
